@router.delete("/api/v1/payouts/scheduled/{payout_id}")
async def cancel_scheduled_payout(
    payout_id: int,
    session_pool: async_sessionmaker = Depends(get_session_pool),
    current_user: User = Depends(get_current_user)
):
    async with session_pool() as session:
        async with session.begin():
            stmt = select(ScheduledPayout).where(
                ScheduledPayout.id == payout_id,
                ScheduledPayout.merchant_id == current_user.merchant_id
            )
            res = await session.execute(stmt)
            payout = res.scalar_one_or_none()
            if not payout:
                raise HTTPException(status_code=404, detail="Payout schedule not found")
            if payout.is_dispatched:
                raise HTTPException(status_code=409, detail="Cannot cancel already dispatched payout")
            payout.status = PayoutStatus.CANCELED
            await session.execute(
                update(PayoutBatch).where(PayoutBatch.id == payout.batch_id).values(active_count=PayoutBatch.active_count - 1)
            )
    return {"canceled": True, "payout_id": payout_id}
